      var s = Math.max(0, num(emp.salesAmount));
      var due = roundMoney(s * rate);
      matchedSales = roundMoney(matchedSales + s);
      contribution = roundMoney(contribution + due);
      var key = emp.id != null && emp.id !== "" ? String(emp.id) : String(emp.name || "");
