      if (cond && typeof cond === 'object') {
        normalizeConditionsRoleEmployeeExclusive(cond);
        sortPoolConditionLoadKeys(Object.keys(cond)).forEach(function(type) {
          if (type === 'weekdays') {
            addTipClaimSalesCondition('weekday', true);
            setTipClaimSalesConditionValue('weekday', cond.weekdays);
            return;
          }
          addTipClaimSalesCondition(type, true);
          if (type === 'role') setTipClaimSalesConditionValue(type, { role: cond.role || [], employees: cond.employees || [] });
          else if (type === 'employee') setTipClaimSalesConditionValue(type, { employeeRoles: cond.employeeRoles, employees: cond.employee });
          else setTipClaimSalesConditionValue(type, cond[type]);
        });
      }
      if (!existingTipClaimSalesConditions['revenueType']) {
        addTipClaimSalesCondition('revenueType', true);
        if (cond && cond.revenueType) setTipClaimSalesConditionValue('revenueType', cond.revenueType);
      }
      updateTipClaimSalesConditionMenu();
